using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table for nibble bit-reversal: index 0..15 → reversed nibble
    private static ReadOnlySpan<byte> NibbleLut => [
        0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
        0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
    ];

    public static void ReverseInPlace(Span<byte> data)
    {
        int i = 0;

        if (Vector256.IsHardwareAccelerated)
        {
            var lut = Vector256.Create(NibbleLut);
            var mask = Vector256.Create((byte)0x0F);

            int lastBlockStart = data.Length - Vector256<byte>.Count;
            ref byte ptr = ref MemoryMarshal.GetReference(data);

            for (; i <= lastBlockStart; i += Vector256<byte>.Count)
            {
                var vec = Vector256.LoadUnsafe(ref ptr, (nuint)i);
                var lo = vec & mask;
                var hi = Vector256.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & mask;
                // Reverse: swap nibbles and use LUT to reverse each nibble
                var reversedLo = Vector256.Shuffle(lut, lo);
                var reversedHi = Vector256.Shuffle(lut, hi);
                var result = Vector256.ShiftRightLogical(reversedLo.AsUInt16(), 4).AsByte() | reversedHi;
                // Shift left by 4 instead of shift right for the high nibble result
                result = (reversedLo << 4) | reversedHi;
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
        }
        else if (Vector128.IsHardwareAccelerated)
        {
            var lut = Vector128.Create(NibbleLut);
            var mask = Vector128.Create((byte)0x0F);

            int lastBlockStart = data.Length - Vector128<byte>.Count;
            ref byte ptr = ref MemoryMarshal.GetReference(data);

            for (; i <= lastBlockStart; i += Vector128<byte>.Count)
            {
                var vec = Vector128.LoadUnsafe(ref ptr, (nuint)i);
                var lo = vec & mask;
                var hi = Vector128.ShiftRightLogical(vec.AsUInt16(), 4).AsByte() & mask;
                var reversedLo = Vector128.Shuffle(lut, lo);
                var reversedHi = Vector128.Shuffle(lut, hi);
                var result = (reversedLo << 4) | reversedHi;
                result.StoreUnsafe(ref ptr, (nuint)i);
            }
        }

        // Scalar fallback for remaining bytes
        for (; i < data.Length; i++)
        {
            byte b = data[i];
            b = (byte)((NibbleLut[b & 0x0F] << 4) | NibbleLut[b >> 4]);
            data[i] = b;
        }
    }
}

